      "keystrokes": "cat > scripts/generate_palette.mjs << 'EOF'
import http from 'http';

let model = 'default';
let input = ['N', 'N', 'N', 'N', 'N'];
let pretty = false;

const args = process.argv.slice(2);
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--model' && args[i + 1]) {
    model = args[++i];
  } else if (args[i] === '--input' && args[i + 1]) {
    input = args.slice(++i);
    break;
  } else if (args[i] === '--pretty') {
    pretty = true;
  }
}

const body = JSON.stringify({ model, input });
const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/api/',
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Content-Length': body.length }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    const result = JSON.parse(data);
    console.log(JSON.stringify(result, null, 2));
    if (pretty && result.palette) {
      console.log('\n### Generated Palette');
      result.palette.forEach((rgb, i) => {
        const hex = '#' + rgb.map(x => x.toString(16).padStart(2, '0')).join('');
        console.log(`- ${hex} (${rgb.join(', ')})`);
      });
    }
  });
});

req.on('error', (e) => console.error(e.message));
req.write(body);
req.end();
EOF\n",
      "duration": 0.1
    }
  ]
}

